d = body()
op = op_of(d, 'orders')
MINE = '(o.IdpUserId = ' + str(uid) + (' OR (o.IdpUserId IS NULL AND lower(o.Email) = ' + q(email) + ')' if email else '') + ')'
if op == 'orders':
